  let numerator = D * G * F;
  let denominator = 4.0 * NdotV * NdotL + 1e-5;
  let specular = numerator / denominator;

  let kS = F;
  let kD = (vec3f(1.0) - kS) * (1.0 - material.metallic);
  let diffuse = kD * material.baseColor.rgb / PI;

