  let val_dy = textureSample(waterTexture, waterSampler, vec2f(wrappedUv.x, clamp(wrappedUv.y + u.delta.y, 0.0, 1.0))).r;

  let dx = vec3f(u.delta.x, val_dx - info.r, 0.0);
